// Парсим Telegram widget страницу (t.me/s/channel)
const input = $input.first().json;

// Проверяем на ошибки
if (input.error || !input.data) {
  console.log('Ошибка загрузки Telegram:', input.error || 'пустой ответ');
  return [];
}

const html = input.data;
const items = [];
const sourceData = $('Только активные').first().json;

// Ищем посты с классом tgme_widget_message
const postRegex = /<div[^>]*class="[^"]*tgme_widget_message_wrap[^"]*"[^>]*>[\s\S]*?<div[^>]*class="[^"]*tgme_widget_message [^"]*"[^>]*data-post="([^"]+)"[^>]*>([\s\S]*?)<\/div>\s*<\/div>\s*<\/div>/gi;

let match;
while ((match = postRegex.exec(html)) !== null && items.length < 10) {
  const postId = match[1];
  const postHtml = match[2];

  // Текст поста
  const textMatch = postHtml.match(/<div[^>]*class="[^"]*tgme_widget_message_text[^"]*"[^>]*>([\s\S]*?)<\/div>/i);
  let text = textMatch ? textMatch[1] : '';

  // Убираем HTML теги, оставляем текст
  text = text
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .trim();

  // Дата
  const dateMatch = postHtml.match(/datetime="([^"]+)"/i);
  const pubDate = dateMatch ? dateMatch[1] : new Date().toISOString();

  // Ссылка на пост
  const link = `https://t.me/${postId}`;

  // Фото - ищем в background-image
  let mediaUrl = '';
  const bgMatch = postHtml.match(/background-image:\s*url\(['"]?([^'"\)]+)['"]?\)/i);
  if (bgMatch) {
    mediaUrl = bgMatch[1];
  }

  // Также проверяем тег img
  if (!mediaUrl) {
    const imgMatch = postHtml.match(/<img[^>]*src="([^"]+)"[^>]*>/i);
    if (imgMatch) {
      mediaUrl = imgMatch[1];
    }
  }

  // Берём только посты с достаточным текстом
  if (text && text.length > 30) {
    items.push({
      title: text.substring(0, 100).replace(/\n/g, ' '),
      link,
      description: text.substring(0, 1500),
      pubDate,
      mediaUrl,
      source_id: sourceData.id || 'telegram',
      source_name: sourceData.name || 'Telegram',
      source_type: 'telegram'
    });
  }
}

console.log(`Telegram: найдено ${items.length} постов`);
return items.map(item => ({ json: item }));

// Парсим RSS XML
const input = $input.first().json;

// Проверяем на ошибки
if (input.error || !input.data) {
  console.log('Ошибка загрузки RSS:', input.error || 'пустой ответ');
  return [];
}

const xml = input.data;
const items = [];
const sourceData = $('Только активные').first().json;

// Парсим RSS items
const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
let match;

while ((match = itemRegex.exec(xml)) !== null && items.length < 10) {
  const itemXml = match[1];

  const getTag = (tag) => {
    // Поддержка CDATA и обычного контента
    const regex = new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\\/${tag}>|<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i');
    const m = itemXml.match(regex);
    return m ? (m[1] || m[2] || '').trim() : '';
  };

  const title = getTag('title');
  const link = getTag('link');
  let description = getTag('description');
  const pubDate = getTag('pubDate');

  // Убираем HTML из description
  description = description
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .trim();

  // Ищем медиа
  let mediaUrl = '';

  // enclosure (стандартный RSS)
  const enclosureMatch = itemXml.match(/<enclosure[^>]*url=["']([^"']+)["'][^>]*>/i);
  if (enclosureMatch) mediaUrl = enclosureMatch[1];

  // media:content
  if (!mediaUrl) {
    const mediaMatch = itemXml.match(/<media:content[^>]*url=["']([^"']+)["'][^>]*>/i);
    if (mediaMatch) mediaUrl = mediaMatch[1];
  }

  // image внутри item
  if (!mediaUrl) {
    const imgMatch = itemXml.match(/<image[^>]*>([\s\S]*?)<\/image>/i);
    if (imgMatch) {
      const urlMatch = imgMatch[1].match(/<url>([^<]+)<\/url>/i);
      if (urlMatch) mediaUrl = urlMatch[1];
    }
  }

  // Пропускаем служебные сообщения rss.app
  if (title && !title.includes('Trial has Expired') && !title.includes('Action required')) {
    items.push({
      title,
      link,
      description: description.substring(0, 1500),
      pubDate,
      mediaUrl,
      source_id: sourceData.id || 'rss',
      source_name: sourceData.name || 'RSS',
      source_type: 'rss'
    });
  }
}

console.log(`RSS: найдено ${items.length} постов`);
return items.map(item => ({ json: item }));

// Парсим VK публичную страницу
const input = $input.first().json;

// Проверяем на ошибки
if (input.error || !input.data) {
  console.log('Ошибка загрузки VK:', input.error || 'пустой ответ');
  return [];
}

const html = input.data;
const items = [];
const sourceData = $('Только активные').first().json;

// VK использует JSON в page для постов
// Ищем посты в формате wall_post
const postRegex = /<div[^>]*class="[^"]*wall_item[^"]*"[^>]*id="post([^"]+)"[^>]*>([\s\S]*?)<\/div>\s*<\/div>\s*<\/div>/gi;

// Альтернативный парсинг через data-post-id
const altPostRegex = /<div[^>]*data-post-id="([^"]+)"[^>]*>([\s\S]*?)<div[^>]*class="[^"]*wall_post_cont[^"]*"[^>]*>([\s\S]*?)<\/div>/gi;

let match;

// Простой парсинг текста постов
const textBlocks = html.match(/<div[^>]*class="[^"]*wall_post_text[^"]*"[^>]*>([\s\S]*?)<\/div>/gi) || [];

for (let i = 0; i < Math.min(textBlocks.length, 10); i++) {
  const block = textBlocks[i];
  let text = block
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .trim();

  if (text && text.length > 30) {
    items.push({
      title: text.substring(0, 100).replace(/\n/g, ' '),
      link: sourceData.url || 'https://vk.com',
      description: text.substring(0, 1500),
      pubDate: new Date().toISOString(),
      mediaUrl: '',
      source_id: sourceData.id || 'vk',
      source_name: sourceData.name || 'VK',
      source_type: 'vk'
    });
  }
}

console.log(`VK: найдено ${items.length} постов`);
return items.map(item => ({ json: item }));

// Создаём hash для проверки дублей + фильтрация
const crypto = require('crypto');

const items = $input.all();
const result = [];

// Стоп-слова для фильтрации рекламы
const stopWords = ['ERID', 'erid', 'реклама', 'Реклама', 'РЕКЛАМА', 'партнёрский', 'партнерский', 'промокод', '#реклама', '#ad', 'спонсор'];

for (const item of items) {
  const data = item.json;
  const text = (data.title || '') + ' ' + (data.description || '');

  // Проверяем на стоп-слова
  const hasStopWord = stopWords.some(word => text.includes(word));
  if (hasStopWord) {
    console.log('Пропускаем рекламу:', data.title?.substring(0, 50));
    continue;
  }

  // Создаём hash
  const hashInput = (data.title || '') + (data.pubDate || '');
  const hash = crypto.createHash('md5').update(hashInput).digest('hex').substring(0, 12);

  result.push({
    json: {
      ...data,
      content_hash: hash
    }
  });
}

console.log(`После фильтрации: ${result.length} постов`);
return result;

// Убираем уже опубликованные новости
const news = $('Фильтруем и создаём hash').all();
const published = $('Читаем опубликованные').all();

// Собираем все hash опубликованных
const publishedHashes = new Set(
  published.map(p => p.json.content_hash).filter(Boolean)
);

console.log(`Опубликовано ранее: ${publishedHashes.size} постов`);

// Фильтруем новые
const newItems = news.filter(item => 
  !publishedHashes.has(item.json.content_hash)
);

console.log(`Новых постов: ${newItems.length}`);

// Берём только 1 новость для публикации
if (newItems.length === 0) {
  console.log('Нет новых постов для публикации');
  return [];
}

// Сортируем по дате (новые первые)
newItems.sort((a, b) => {
  const dateA = new Date(a.json.pubDate || 0);
  const dateB = new Date(b.json.pubDate || 0);
  return dateB - dateA;
});

return [newItems[0]];

// Собираем данные для LLM
const news = $('Убираем дубли').first().json;
const settingsRows = $('Читаем настройки').all();

// Преобразуем настройки в объект
const settings = {};
for (const row of settingsRows) {
  settings[row.json.key] = row.json.value;
}

// Промпт по умолчанию (из задания)
const defaultPrompt = `Прочитай новость о бесплатном событии в Петербурге и создай пост для Telegram по следующим правилам:

1. Используй эмодзи для категории в начале (🎭 культура, 🎨 выставки, 🎵 концерты, 🏃 спорт, 👨‍👩‍👧‍👦 для детей, 🎉 фестивали, 📚 лекции)

2. Структура поста:
   - Эмодзи + Название события
   - 📅 Дата и время
   - 📍 Место проведения (адрес)
   - 💰 Стоимость (БЕСПЛАТНО или цена)
   - Краткое описание (2-3 предложения)
   - ℹ️ Дополнительная информация (регистрация, возраст и т.д.)

3. Правила оформления:
   - Убери все HTML-теги
   - Удали рекламные ссылки (clck.ru, bit.ly и т.д.)
   - Убери ERID и пометки о рекламе
   - Не добавляй от себя информацию, которой нет в источнике
   - Если нет точной даты - напиши "уточняйте на месте"

4. Ограничения:
   - Максимум 800 символов общая длина поста
   - Описание не более 500 символов
   - Используй переносы строк для читабельности

ЧЕКЛИСТ перед отправкой:
✓ Есть эмодзи категории в начале
✓ Указана дата/время события
✓ Есть адрес или место
✓ Понятно что бесплатно
✓ Нет рекламных ссылок и стоп-слов
✓ Текст читается без кликов по ссылкам`;

const prompt = settings.prompt || defaultPrompt;
const maxLength = settings.max_post_length || 800;

const userMessage = `${prompt}

---
ИСХОДНАЯ НОВОСТЬ:

Заголовок: ${news.title}

Полный текст: ${news.description}

Дата публикации: ${news.pubDate}

Источник: ${news.source_name}

---
Максимальная длина поста: ${maxLength} символов.
Выдай ТОЛЬКО текст поста, без пояснений.`;

return [{
  json: {
    ...news,
    settings,
    userMessage,
    maxLength
  }
}];

// Извлекаем текст поста из ответа LLM
const input = $input.first().json;
const originalData = $('Готовим промпт').first().json;

let postText = '';

// Разные форматы ответа OpenAI
if (input.message && input.message.content) {
  postText = input.message.content;
} else if (input.text) {
  postText = input.text;
} else if (input.content) {
  postText = input.content;
} else if (typeof input === 'string') {
  postText = input;
}

// Очищаем от возможных markdown блоков
postText = postText
  .replace(/```[\s\S]*?```/g, '')
  .replace(/^```\w*\n?/gm, '')
  .replace(/```$/gm, '')
  .trim();

// Проверяем длину
const maxLength = originalData.maxLength || 800;
if (postText.length > maxLength + 100) {
  console.log(`Пост слишком длинный (${postText.length}), обрезаем`);
  postText = postText.substring(0, maxLength) + '...';
}

console.log(`Пост готов, длина: ${postText.length} символов`);

return [{
  json: {
    post_text: postText,
    media_url: originalData.mediaUrl || '',
    content_hash: originalData.content_hash,
    title: originalData.title,
    link: originalData.link,
    source_id: originalData.source_id,
    source_name: originalData.source_name,
    settings: originalData.settings
  }
}];

// Fallback если фото не загрузилось - отправляем текст
const input = $input.first().json;
const originalData = $('Извлекаем пост').first().json;

// Если была ошибка с фото, возвращаем данные для отправки текстом
if (input.error || input.ok === false) {
  console.log('Ошибка отправки фото, отправим только текст');
  return [{ json: originalData }];
}

// Успешно отправлено с фото
return [{ json: { ...originalData, sent_with_photo: true } }];

